def slugify(text):
    """Lower-case ASCII slug: words joined by single dashes, no edge dashes."""
    normalized = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode()
    lowered = normalized.lower()
    dashed = re.sub(r"[^a-z0-9]", "-", lowered)
    return dashed.strip("-")

